CREATE TABLE strategy_candidates (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),client_request_id TEXT NOT NULL UNIQUE,generated_strategy_json JSONB NOT NULL,reasoning TEXT NOT NULL,evidence_ids_json JSONB NOT NULL,confidence DOUBLE PRECISION NOT NULL CHECK(confidence BETWEEN 0 AND 1),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at TIMESTAMPTZ NOT NULL,decided_at TIMESTAMPTZ,approved_at TIMESTAMPTZ,approved_by TEXT,rejected_at TIMESTAMPTZ,rejected_by TEXT,reject_reason TEXT);
CREATE TABLE strategy_feedback (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),strategy_id TEXT NOT NULL REFERENCES growth_strategies(id),feedback_type TEXT NOT NULL CHECK(feedback_type IN ('effective','normal','wrong')),content TEXT NOT NULL,impact INTEGER NOT NULL CHECK(impact BETWEEN 1 AND 5),created_at TIMESTAMPTZ NOT NULL);
